"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

from datetime import datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    if count == 0:
        return []

    fields = expr.split()
    if len(fields) != 5:
        raise CronError("Expression must have exactly 5 fields")

    minute_unrestricted, minute_values = _parse_cron_field(fields[0], 0, 59)
    hour_unrestricted, hour_values = _parse_cron_field(fields[1], 0, 23)
    dom_unrestricted, dom_values = _parse_cron_field(fields[2], 1, 31)
    month_unrestricted, month_values = _parse_month_field(fields[3])
    dow_unrestricted, dow_values = _parse_dow_field(fields[4])

    current = start + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    results = []
    max_search = start + timedelta(days=365*5)

    while len(results) < count and current <= max_search:
        if _matches(current, minute_values, hour_values, dom_unrestricted, dom_values,
                    month_values, dow_unrestricted, dow_values):
            results.append(current)
        current += timedelta(minutes=1)

    if len(results) < count:
        raise CronError(f"No firing exists within five years of {start}")

    return results


def _parse_cron_field(field_text: str, low: int, high: int) -> tuple[bool, set[int]]:
    """Parse a cron field and return (is_unrestricted, values)."""
    is_unrestricted = (field_text == '*')
    values = _parse_field(field_text, low, high)
    return is_unrestricted, values


def _parse_month_field(field_text: str) -> tuple[bool, set[int]]:
    """Parse a month field with name support."""
    month_names = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }
    is_unrestricted = (field_text == '*')
    values = _parse_field(field_text, 1, 12, month_names)
    return is_unrestricted, values


def _parse_dow_field(field_text: str) -> tuple[bool, set[int]]:
    """Parse a day-of-week field with name support and 7->0 conversion."""
    dow_names = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }
    is_unrestricted = (field_text == '*')
    values = _parse_field(field_text, 0, 7, dow_names)

    if 7 in values:
        values.discard(7)
        values.add(0)

    for v in values:
        if v < 0 or v > 6:
            raise CronError(f"Value {v} out of range [0, 6] for day-of-week")

    return is_unrestricted, values


def _parse_field(field_text: str, low: int, high: int, name_map: dict = None) -> set[int]:
    """Parse a single cron field and return the set of valid values."""
    if name_map is None:
        name_map = {}

    values = set()

    for term in field_text.split(','):
        term = term.strip()

        if term == '*':
            values.update(range(low, high + 1))
        elif '/' in term:
            if term.startswith('*/'):
                try:
                    step = int(term[2:])
                except ValueError:
                    raise CronError(f"Invalid step in term: {term}")
                if step < 1:
                    raise CronError(f"Step must be >= 1, got {step}")
                values.update(range(low, high + 1, step))
            elif '-' in term:
                range_part, step_part = term.rsplit('/', 1)
                try:
                    step = int(step_part)
                except ValueError:
                    raise CronError(f"Invalid step in term: {term}")
                if step < 1:
                    raise CronError(f"Step must be >= 1, got {step}")

                range_parts = range_part.split('-')
                if len(range_parts) != 2:
                    raise CronError(f"Invalid range in term: {term}")

                a = _parse_value(range_parts[0], name_map)
                b = _parse_value(range_parts[1], name_map)

                if a > b:
                    raise CronError(f"Range low > high in term: {term}")

                values.update(range(a, b + 1, step))
            else:
                parts = term.split('/', 1)
                base = _parse_value(parts[0], name_map)
                try:
                    step = int(parts[1])
                except ValueError:
                    raise CronError(f"Invalid step in term: {term}")
                if step < 1:
                    raise CronError(f"Step must be >= 1, got {step}")

                values.update(range(base, high + 1, step))
        elif '-' in term:
            parts = term.split('-')
            if len(parts) != 2:
                raise CronError(f"Invalid range in term: {term}")

            a = _parse_value(parts[0], name_map)
            b = _parse_value(parts[1], name_map)

            if a > b:
                raise CronError(f"Range low > high in term: {term}")

            values.update(range(a, b + 1))
        else:
            v = _parse_value(term, name_map)
            values.add(v)

    for v in values:
        if v < low or v > high:
            raise CronError(f"Value {v} out of range [{low}, {high}]")

    return values


def _parse_value(s: str, name_map: dict) -> int:
    """Parse a single value, which could be a number or a name."""
    s_upper = s.upper()
    if s_upper in name_map:
        return name_map[s_upper]

    try:
        return int(s)
    except ValueError:
        raise CronError(f"Invalid value: {s}")


def _matches(current: datetime, minute_values: set[int], hour_values: set[int],
             dom_unrestricted: bool, dom_values: set[int], month_values: set[int],
             dow_unrestricted: bool, dow_values: set[int]) -> bool:
    """Check if a datetime matches the cron expression."""
    if current.minute not in minute_values:
        return False
    if current.hour not in hour_values:
        return False
    if current.month not in month_values:
        return False

    dow = (current.weekday() + 1) % 7

    if dom_unrestricted and dow_unrestricted:
        return True
    elif dom_unrestricted:
        return dow in dow_values
    elif dow_unrestricted:
        return current.day in dom_values
    else:
        return (current.day in dom_values) or (dow in dow_values)
